import { useState } from 'react';
import {
  JxToggle,
  JxSlider,
  JxSwitch,
  JxDivider,
  JxSelect,
  JxBadge,
} from '@jinx-ui/react';

type ThemeValue = 'light' | 'dark' | 'system';
type FontValue = 'sans' | 'display' | 'mono';

interface AppearanceSettingsState {
  theme: ThemeValue;
  scale: number;
  dense: boolean;
  font: FontValue;
}

interface AppearanceSettingsProps {
  onChange?: (state: AppearanceSettingsState) => void;
}

const themeLabels: Record<ThemeValue, string> = {
  light: 'Светлая',
  dark: 'Тёмная',
  system: 'Системная',
};

export default function AppearanceSettings({ onChange }: AppearanceSettingsProps) {
  const [theme, setTheme] = useState<ThemeValue>('system');
  const [scale, setScale] = useState(100);
  const [dense, setDense] = useState(false);
  const [font, setFont] = useState<FontValue>('sans');

  const emit = (next: Partial<AppearanceSettingsState>) => {
    onChange?.({ theme, scale, dense, font, ...next });
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 24 }}>
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
        <h2 style={{ fontFamily: 'var(--jx-font-display)', color: 'var(--jx-text)', margin: 0 }}>
          Внешний вид
        </h2>
        <JxBadge tone="accent">{themeLabels[theme]}</JxBadge>
      </div>

      <JxToggle
        items={[
          { value: 'light', label: 'Светлая' },
          { value: 'dark', label: 'Тёмная' },
          { value: 'system', label: 'Системная' },
        ]}
        value={theme}
        onValueChange={(value) => {
          const next = value as ThemeValue;
          setTheme(next);
          emit({ theme: next });
        }}
      />

      <JxSlider
        label="Масштаб интерфейса"
        value={scale}
        min={80}
        max={140}
        step={5}
        unit="%"
        showOutput
        onValueChange={(value) => {
          setScale(value);
          emit({ scale: value });
        }}
      />

      <JxSwitch
        label="Плотная вёрстка"
        checked={dense}
        onChange={(event) => {
          const value = event.target.checked;
          setDense(value);
          emit({ dense: value });
        }}
      />

      <JxDivider label="Ещё" />

      <JxSelect
        label="Шрифт интерфейса"
        options={[
          { value: 'sans', label: 'Inter Tight' },
          { value: 'display', label: 'Fraunces' },
          { value: 'mono', label: 'JetBrains Mono' },
        ]}
        value={font}
        onValueChange={(value) => {
          const next = value as FontValue;
          setFont(next);
          emit({ font: next });
        }}
      />
    </div>
  );
}

